function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 2000) return 's needs 1 to 2,000 characters.';
  if (!/^[a-zA-Z]+$/.test(s)) return 's contains only English letters.';
  return null;
}

