function longestPalindrome(s) {
  const counts = new Map();
  for (const ch of s) {
    counts.set(ch, (counts.get(ch) || 0) + 1);
  }
  let length = 0;
  let hasOdd = false;
  for (const count of counts.values()) {
    length += count - (count % 2);
    if (count % 2 === 1) {
      hasOdd = true;
    }
  }
  if (hasOdd) {
    length += 1;
  }
  return length;
}

