function longestPalindrome(s) {
  // Pair letters off as they arrive; whatever is left unpaired can give one middle letter.
  const unpaired = new Set();
  let pairs = 0;
  for (const ch of s) {
    if (unpaired.has(ch)) { unpaired.delete(ch); pairs++; }
    else unpaired.add(ch);
  }
  return 2 * pairs + (unpaired.size > 0 ? 1 : 0);
}

