function generate(rand, size) {
  const ALL = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const letters = size === 'large'
    ? ALL.slice(0, 1 + Math.floor(rand() * 52))
    : ['a', 'aA', 'abB', 'abcABC', ALL][Math.floor(rand() * 5)];
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 12);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * letters.length)];
  return [s];
}
